void initFromPriceDiscTable(PriceDiscTable _priceDiscTable)
{
    next initFromPriceDiscTable(_priceDiscTable);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance())
        && _priceDiscTable.PriceComponentCombination)
    {
        this.PriceComponentCode = GUPPriceComponentCodePriceAttributeGroupCombination::find(_priceDiscTable.PriceComponentCombination).PriceComponentCodeName;

        PriceDiscAdmTrans priceDiscAdmTrans;
        select firstonly priceDiscAdmTrans
            where priceDiscAdmTrans.RecId == _priceDiscTable.OriginalPriceDiscAdmTransRecId;
        this.JournalNum = priceDiscAdmTrans.JournalNum;
    }
}

public boolean equalBasePriceLineMap(GUPSalesBasePriceLineMap _basePriceLineMap) { boolean equal = false;
if (this.RefTableId == _basePriceLineMap.RefTableId && this.RefRecId == _basePriceLineMap.RefRecId && this.ItemCode == _basePriceLineMap.ItemCode && this.AccountCode == _basePriceLineMap.AccountCode && this.ItemRelation == _basePriceLineMap.ItemRelation && this.AccountRelation == _basePriceLineMap.AccountRelation && this.QuantityAmount == _basePriceLineMap.QuantityAmount && this.FromDate == _basePriceLineMap.FromDate && this.Amount == _basePriceLineMap.Amount && this.Currency == _basePriceLineMap.Currency && this.Percent1 == _basePriceLineMap.Percent1 && this.Percent2 == _basePriceLineMap.Percent2 && this.PriceUnit == _basePriceLineMap.PriceUnit && this.Relation == _basePriceLineMap.Relation && this.UnitId == _basePriceLineMap.UnitId && this.Markup == _basePriceLineMap.Markup && this.AllocateMarkup == _basePriceLineMap.AllocateMarkup && this.Module == _basePriceLineMap.Module && this.InventDimId == _basePriceLineMap.InventDimId) { equal = true; }
return equal; }
